-- Restore the final active backend navigation catalog that was accidentally
-- omitted when the migration history was consolidated. Existing rows win so
-- newer Toonflow routes and labels are never overwritten.


-- The consolidated baseline kept button permissions below a retired duplicate
-- AI menu group. The restored AI catalog has the equivalent active permissions,
-- so retire any permission whose business menu no longer exists.
UPDATE public.system_menu AS child
SET deleted = 1,
    updater = 'system',
    update_time = now()
WHERE child.deleted = 0
  AND child.type = 3
  AND child.parent_id <> 0
  AND NOT EXISTS (
    SELECT 1
    FROM public.system_menu AS parent
    WHERE parent.id = child.parent_id
      AND parent.deleted = 0
  );

SELECT setval(
  'public.system_menu_seq',
  GREATEST((SELECT COALESCE(MAX(id), 1) FROM public.system_menu), 1),
  true
);
